CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, appliedAt INTEGER NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,displayName TEXT NOT NULL,passwordHash TEXT NOT NULL,role TEXT NOT NULL,scope TEXT NOT NULL DEFAULT '{}',active INTEGER NOT NULL DEFAULT 1,createdAt INTEGER NOT NULL);
CREATE TABLE sessions(tokenHash TEXT PRIMARY KEY,userId TEXT NOT NULL REFERENCES users(id),csrfToken TEXT NOT NULL,expiresAt INTEGER NOT NULL);
CREATE TABLE collector_tokens(tokenHash TEXT PRIMARY KEY,userId TEXT NOT NULL REFERENCES users(id),expiresAt INTEGER NOT NULL);
CREATE TABLE source_systems(id TEXT PRIMARY KEY,name TEXT NOT NULL,hostname TEXT NOT NULL,url TEXT NOT NULL,adapter TEXT NOT NULL,version TEXT NOT NULL,adapterStatus TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,lastSyncedAt INTEGER,lastSuccessAt INTEGER,lastError TEXT);
CREATE TABLE source_field_mappings(sourceSystem TEXT PRIMARY KEY REFERENCES source_systems(id),config TEXT NOT NULL);
CREATE TABLE source_status_mappings(sourceSystem TEXT PRIMARY KEY REFERENCES source_systems(id),config TEXT NOT NULL);
CREATE TABLE agencies(id TEXT PRIMARY KEY,sourceSystem TEXT NOT NULL,name TEXT NOT NULL);
CREATE TABLE departments(id TEXT PRIMARY KEY,sourceSystem TEXT NOT NULL,name TEXT NOT NULL,agencyId TEXT);
CREATE TABLE officers(id TEXT PRIMARY KEY,sourceSystem TEXT NOT NULL,name TEXT NOT NULL,agencyId TEXT,departmentId TEXT);
CREATE TABLE procedures(id TEXT PRIMARY KEY,sourceSystem TEXT NOT NULL,code TEXT NOT NULL,name TEXT NOT NULL);
CREATE TABLE cases(id TEXT PRIMARY KEY,sourceSystem TEXT NOT NULL REFERENCES source_systems(id),caseCode TEXT NOT NULL,sourceRecordId TEXT,sourceCaseId TEXT,agencyId TEXT,departmentId TEXT,officerId TEXT,procedureCode TEXT,normalizedStatus TEXT NOT NULL,receivedAt TEXT,dueAt TEXT,alertLevel TEXT NOT NULL,riskScore INTEGER NOT NULL,completionResult TEXT,needsReview INTEGER NOT NULL DEFAULT 0,data TEXT NOT NULL,evaluation TEXT NOT NULL,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL,lastSyncedAt INTEGER NOT NULL,nextRecalculationAt INTEGER NOT NULL);
CREATE TABLE case_aliases(sourceSystem TEXT NOT NULL,kind TEXT NOT NULL,value TEXT NOT NULL,caseId TEXT NOT NULL REFERENCES cases(id),PRIMARY KEY(sourceSystem,kind,value));
CREATE TABLE case_history(id TEXT PRIMARY KEY,caseId TEXT NOT NULL REFERENCES cases(id),kind TEXT NOT NULL,changes TEXT NOT NULL,actorId TEXT,jobId TEXT,createdAt INTEGER NOT NULL);
CREATE TABLE sync_jobs(id TEXT PRIMARY KEY,sourceId TEXT NOT NULL,initiatedBy TEXT NOT NULL,kind TEXT NOT NULL,batchId TEXT,startedAt INTEGER NOT NULL,completedAt INTEGER,status TEXT NOT NULL,recordsFetched INTEGER NOT NULL DEFAULT 0,recordsCreated INTEGER NOT NULL DEFAULT 0,recordsUpdated INTEGER NOT NULL DEFAULT 0,recordsSkipped INTEGER NOT NULL DEFAULT 0,recordsFailed INTEGER NOT NULL DEFAULT 0,error TEXT,errors TEXT NOT NULL DEFAULT '[]',UNIQUE(initiatedBy,sourceId,batchId));
CREATE TABLE alert_rules(scopeType TEXT NOT NULL,scopeId TEXT NOT NULL,config TEXT NOT NULL,updatedAt INTEGER NOT NULL,PRIMARY KEY(scopeType,scopeId));
CREATE TABLE alerts(id TEXT PRIMARY KEY,caseId TEXT NOT NULL UNIQUE REFERENCES cases(id),type TEXT NOT NULL,level TEXT NOT NULL,message TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL,firstDetectedAt INTEGER NOT NULL,lastDetectedAt INTEGER NOT NULL,acknowledgedAt INTEGER,acknowledgedBy TEXT,createdAt INTEGER NOT NULL);
CREATE TABLE alert_history(id TEXT PRIMARY KEY,alertId TEXT NOT NULL REFERENCES alerts(id),oldLevel TEXT,newLevel TEXT,status TEXT NOT NULL,createdAt INTEGER NOT NULL);
CREATE TABLE notifications(id TEXT PRIMARY KEY,alertId TEXT NOT NULL REFERENCES alerts(id),caseId TEXT NOT NULL REFERENCES cases(id),message TEXT NOT NULL,createdAt INTEGER NOT NULL);
CREATE TABLE system_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,userId TEXT,action TEXT NOT NULL,target TEXT,details TEXT NOT NULL,createdAt INTEGER NOT NULL);
CREATE INDEX cases_source ON cases(sourceSystem,updatedAt);
CREATE INDEX cases_code ON cases(sourceSystem,caseCode);
CREATE INDEX cases_record ON cases(sourceSystem,sourceRecordId);
CREATE INDEX cases_status ON cases(normalizedStatus);
CREATE INDEX cases_agency ON cases(agencyId);
CREATE INDEX cases_department ON cases(departmentId);
CREATE INDEX cases_officer ON cases(officerId);
CREATE INDEX cases_procedure ON cases(procedureCode);
CREATE INDEX cases_due ON cases(dueAt);
CREATE INDEX cases_received ON cases(receivedAt);
CREATE INDEX cases_alert ON cases(alertLevel,riskScore);
CREATE INDEX cases_risk ON cases(riskScore);
CREATE INDEX cases_next ON cases(nextRecalculationAt);
CREATE INDEX cases_updated ON cases(updatedAt);
CREATE INDEX alerts_status ON alerts(status,level);
CREATE INDEX history_case ON case_history(caseId,createdAt);
CREATE INDEX audit_time ON audit_logs(createdAt);
CREATE INDEX jobs_source ON sync_jobs(sourceId,startedAt);
CREATE INDEX sessions_expiry ON sessions(expiresAt);
CREATE INDEX tokens_expiry ON collector_tokens(expiresAt);
